import './photo-instance-import.mjs';
const by=id=>document.getElementById(id),api=()=>globalThis.coexLayerLayout;
const panel=document.createElement('details');panel.id='supportLassoPanel';panel.innerHTML=`<summary>받침 등 배경 속 요소 직접 분리</summary><p class="layer-help">먼저 사진 속 물체를 분리한 뒤 배경 또는 같은 사진의 물체를 선택하세요. 원본 사진을 보며 받침을 둘러 그리면 남은 배경에서 보이는 부분만 독립 레이어로 나눕니다. 상품 뒤 가려진 부분은 투명하게 남습니다.</p><button type="button" class="doc-btn" id="supportOpen">원본에서 분리 영역 그리기</button><div id="supportTools" hidden><p class="layer-help">경계를 따라 마우스나 손가락으로 한 바퀴 둘러 그리세요. 다시 그리면 이전 선을 바꿉니다.</p><div style="overflow:auto;max-height:510px"><canvas id="supportCanvas" aria-label="분리할 영역을 둘러 그리기" style="max-width:100%;max-height:460px;width:auto;height:auto;touch-action:none;cursor:crosshair"></canvas></div><button type="button" class="doc-btn" id="supportApply" disabled>표시 영역을 별도 레이어로 분리</button></div><p id="supportStatus" class="layer-help" role="status" aria-live="polite"></p>`;
by('instanceAnalysisPanel').after(panel);let draft=null,drawing=false,points=[],ticket=0;
const say=t=>by('supportStatus').textContent=t;
const selected=()=>api()?.read()?.objects.find(o=>o.canvas)?.canvas?.getActiveObject();
function valid(d){const s=api()?.read(),active=selected();return s&&s.epoch===d.state.epoch&&s.revision===d.state.revision&&s.objects.includes(d.bg)&&active?.photoInstanceGroup===d.bg.photoInstanceGroup;}
async function decode(src){const im=new Image();im.src=src;await im.decode();return im;}
function raster(im,w,h){const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(im,0,0,w,h);return c;}
function render(){if(!draft)return;const c=by('supportCanvas'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.drawImage(draft.original,0,0);if(points.length){ctx.beginPath();ctx.moveTo(points[0].x,points[0].y);for(const p of points.slice(1))ctx.lineTo(p.x,p.y);if(!drawing&&points.length>=3){ctx.closePath();ctx.fillStyle='rgba(100,63,220,.25)';ctx.fill();}ctx.lineWidth=Math.max(2,c.width/500);ctx.strokeStyle='#693df0';ctx.stroke();}}
by('supportOpen').onclick=async()=>{const id=++ticket,s=api()?.read(),active=selected(),bg=active?.photoInstanceKind==='background'?active:s?.objects.find(o=>o.photoInstanceKind==='background'&&o.photoInstanceGroup===active?.photoInstanceGroup),source=s?.objects.find(o=>o.photoInstanceKind==='source'&&o.photoInstanceGroup===bg?.photoInstanceGroup);draft=null;points=[];by('supportTools').hidden=true;by('supportApply').disabled=true;
 if(!s||!bg||bg.layerLocked||bg.visible===false||!source?.originalPhotoSource){say('분리된 배경 또는 같은 사진의 물체를 선택하고 배경 잠금을 해제하세요.');return;}if(bg.generatedMethod){say('생성 보완 전 배경으로 복원한 뒤 영역을 지정하세요.');return;}
 try{const [original,image]=await Promise.all([decode(source.originalPhotoSource),decode(bg.getSrc())]);if(id!==ticket)return;if(original.naturalWidth!==image.naturalWidth||original.naturalHeight!==image.naturalHeight||image.naturalWidth*image.naturalHeight>4000000)throw Error('사진 크기를 확인할 수 없습니다.');const d={state:s,bg,original,image};if(!valid(d))throw Error('선택이 바뀌었습니다. 다시 열어 주세요.');draft=d;const c=by('supportCanvas');c.width=image.naturalWidth;c.height=image.naturalHeight;by('supportTools').hidden=false;render();say('받침의 바깥 경계를 둘러 그린 뒤 분리하세요.');}catch(e){say(e.message);}};
function point(e){const c=by('supportCanvas'),b=c.getBoundingClientRect();return {x:Math.max(0,Math.min(c.width,(e.clientX-b.left)*c.width/b.width)),y:Math.max(0,Math.min(c.height,(e.clientY-b.top)*c.height/b.height))};}
const c=by('supportCanvas');c.onpointerdown=e=>{if(!draft||!valid(draft)){say('선택이 바뀌었습니다. 다시 열어 주세요.');return;}e.preventDefault();drawing=true;points=[point(e)];by('supportApply').disabled=true;c.setPointerCapture(e.pointerId);render();};c.onpointermove=e=>{if(!drawing)return;points.push(point(e));render();};c.onpointerup=e=>{if(!drawing)return;points.push(point(e));drawing=false;if(c.hasPointerCapture(e.pointerId))c.releasePointerCapture(e.pointerId);by('supportApply').disabled=points.length<3;render();};c.onpointercancel=()=>{drawing=false;points=[];by('supportApply').disabled=true;render();};
by('supportApply').onclick=async()=>{const d=draft;if(!d||!valid(d)||points.length<3){say('영역을 다시 선택하세요.');return;}try{
 const w=c.width,h=c.height,shape=document.createElement('canvas');shape.width=w;shape.height=h;const sx=shape.getContext('2d');sx.beginPath();sx.moveTo(points[0].x,points[0].y);for(const p of points.slice(1))sx.lineTo(p.x,p.y);sx.closePath();sx.fill();const hit=sx.getImageData(0,0,w,h).data,base=raster(d.image,w,h),a=base.getContext('2d').getImageData(0,0,w,h).data,mask=sx.createImageData(w,h);let l=w,t=h,r=-1,b=-1,count=0;
 for(let i=0;i<w*h;i++){const j=i*4,on=hit[j+3]>=128&&a[j+3]>0;mask.data[j+3]=on?255:0;if(on){const x=i%w,y=Math.floor(i/w);l=Math.min(l,x);r=Math.max(r,x);t=Math.min(t,y);b=Math.max(b,y);count++;}}
 if(count<32)throw Error('선택 영역에 배경 픽셀이 충분하지 않습니다. 더 넓게 둘러 주세요.');const mc=sx;mc.putImageData(mask,0,0);mc.globalCompositeOperation='source-in';mc.drawImage(base,0,0);mc.globalCompositeOperation='source-over';const cut=document.createElement('canvas');cut.width=r-l+1;cut.height=b-t+1;cut.getContext('2d').drawImage(shape,l,t,cut.width,cut.height,0,0,cut.width,cut.height);const partSrc=cut.toDataURL('image/png');
 const bgc=base.getContext('2d');bgc.globalCompositeOperation='destination-out';const binary=document.createElement('canvas');binary.width=w;binary.height=h;binary.getContext('2d').putImageData(mask,0,0);bgc.drawImage(binary,0,0);bgc.globalCompositeOperation='source-over';const bgSrc=base.toDataURL('image/png');const [partImage,bgImage]=await Promise.all([decode(partSrc),decode(bgSrc)]);if(!valid(d))return;
 const s=api().read(),F=s.F,o=d.bg,canvas=o.canvas;if(canvas.size()+1>200)throw Error('편집 요소가 200개를 넘습니다.');const matrix=o.calcTransformMatrix(),part=new F.FabricImage(partImage,{originX:'left',originY:'top',scaleX:o.scaleX,scaleY:o.scaleY,angle:o.angle,skewX:o.skewX,skewY:o.skewY,flipX:o.flipX,flipY:o.flipY,opacity:o.opacity,strokeWidth:0,layerName:'직접 분리한 받침·배경 요소',layerRole:'subject',layerRoleInferred:false,layerLocked:false,sourceElementId:(o.sourceElementId||'photo')+':support:'+crypto.randomUUID(),sourceElementType:'picture',cutoutMethod:'manual-background-polygon',perPixelTargetFind:true,photoInstanceGroup:o.photoInstanceGroup,photoInstanceKind:'support',photoInstanceCrop:{x:l,y:t,w:cut.width,h:cut.height}});const center=F.util.transformPoint(new F.Point(l+cut.width/2-o.width/2,t+cut.height/2-o.height/2),matrix);part.setPositionByOrigin(center,'center','center');part.setCoords();o.setElement(bgImage);o.setCoords();canvas.insertAt(canvas.getObjects().indexOf(o)+1,part);canvas.setActiveObject(part);api().commit(s.width,s.height,{epoch:s.epoch,revision:s.revision,apply:true});draft=null;by('supportTools').hidden=true;say('표시한 영역의 보이는 부분을 별도 레이어로 나눴습니다. 가려진 뒷부분은 투명합니다.');
 }catch(e){say(e.message);}};
for(const event of ['coex:layer-source','coex:layer-edit'])window.addEventListener(event,()=>{ticket++;draft=null;drawing=false;by('supportTools').hidden=true;});
